"""EconomicEvaluator: the one place the buyer turns terms into euros. Normal moves, fallbacks and
acceptance all price through it, on the published cost function (`cost.total_cost`) with each
supplier's own standard terms. Supplier economics are estimates: the relationship term is priced
in three scenarios (low / mid / high C), never as a fact."""

import math

from ..cost import RELATIONSHIP_GOALS, closing_terms, supplier_value, total_cost
from .records import CandidatePackage, EvaluatedPackage, SupplierEstimate

SCENARIO = {"low": 0, "mid": 1, "high": 2}  # index into SupplierEstimate.full_cost; high = dearest C


def estimate_supplier(dossier, sid, price, cash_pressure=False):
    """Full cost from the supplier's should-cost row, else the generic one, else 92 % of its price
    (the should-cost error of 5-15 % sets the spread). Cash pressure raises its cost of money."""
    found = dossier.should_cost.get(sid) or dossier.should_cost.get("*") if dossier else None
    if found:
        cost, conf = found
        spread, source = max(conf, 5.0) / 100, "should-cost"
    else:
        cost, spread, source = 0.92 * price, 0.07, "default"
    return SupplierEstimate(
        full_cost=(cost * (1 - spread), cost, cost * (1 + spread)),
        interest_rate=0.12 if cash_pressure else 0.08,
        source=source,
    )


class EconomicEvaluator:
    def __init__(self, case, std=None, estimates=None):
        self.case = case
        self.std = std or {}  # sid -> standard terms from its quote PDFs
        self.estimates = estimates or {}  # sid -> SupplierEstimate
        self.relationship = case["buyer"].get("category_goal") in RELATIONSHIP_GOALS and bool(self.estimates)

    def standard(self, sid):
        """The supplier's standard terms, completed from the case, as `cost.supplier_value` reads them."""
        return closing_terms(self.case, {"unit_price": 0.0}, self.std.get(sid))

    def supplier(self, sid, scenario="mid"):
        est = self.estimates.get(sid)
        if not self.relationship or est is None:
            return None
        return {
            "standard": self.standard(sid),
            "full_cost": est.full_cost[SCENARIO[scenario]],
            "interest_rate": est.interest_rate,
        }

    def c(self, sid, terms, scenario="mid"):
        return total_cost(self.case, terms, self.std.get(sid), self.supplier(sid, scenario))

    def c_alt(self):
        alt = self.case["buyer"].get("alternative") or {}
        return total_cost(self.case, alt["terms"]) if alt.get("terms", {}).get("unit_price") else math.inf

    def cash_theirs(self, sid, terms):
        est = self.estimates.get(sid)
        supplier = {"standard": self.standard(sid), "interest_rate": est.interest_rate if est else 0.08}
        return supplier_value(self.case, terms, supplier)

    def evaluate(self, pkg: CandidatePackage) -> EvaluatedPackage:
        return EvaluatedPackage(
            pkg=pkg,
            c=self.c(pkg.sid, pkg.terms),
            c_high=self.c(pkg.sid, pkg.terms, "high"),
            cash_theirs=self.cash_theirs(pkg.sid, pkg.terms),
        )

    def best_price(self, sid, terms):
        """The price below which C rises again (relationship goals: squeezing costs); 0 without."""
        if not self.relationship:
            return 0.0
        lo, hi = 0.3 * terms["unit_price"], 1.5 * terms["unit_price"]
        for _ in range(60):  # golden section: C is convex in the price
            a, b = lo + (hi - lo) * 0.382, lo + (hi - lo) * 0.618
            if self.c(sid, {**terms, "unit_price": a}) <= self.c(sid, {**terms, "unit_price": b}):
                hi = b
            else:
                lo = a
        return round((lo + hi) / 2, 2)

    def price_for(self, sid, terms, target_c):
        """The highest price (cents, rounded down) at which `terms` costs at most `target_c`, not
        below `best_price`; None if even that price costs more."""
        floor = self.best_price(sid, terms)
        p0 = max(terms["unit_price"], floor + 1.0)
        c0, c1 = self.c(sid, {**terms, "unit_price": p0}), self.c(sid, {**terms, "unit_price": p0 + 1})
        if c1 - c0 <= 0:
            return None
        if not self.relationship:  # C is linear in the price
            p = p0 + (target_c - c0) / (c1 - c0)
        else:  # increasing above best_price: bisect
            lo, hi = floor, p0
            while self.c(sid, {**terms, "unit_price": hi}) < target_c:
                hi *= 1.5
            for _ in range(60):
                mid = (lo + hi) / 2
                lo, hi = (mid, hi) if self.c(sid, {**terms, "unit_price": mid}) <= target_c else (lo, mid)
            p = lo
        p = math.floor(p * 100) / 100
        if p <= 0 or p < floor or self.c(sid, {**terms, "unit_price": p}) > target_c + 0.01:
            return None
        return p

"""BidGenerator: how much to concede this turn (in our C, on our own package) and the complete
term sheets that cost exactly that. Concessions follow the supplier's moves (reciprocity) and
the clock (an aspiration curve), never exceed what the supplier asks, and never go backwards."""

import statistics

from .records import CandidatePackage

MAX_COMBOS = 300  # beyond this: the C-optimal combination and its one-field neighbours


def anchor_price(case, dossier, their_price):
    """Our opening price: the lowest defensible figure - never above the current price in a price
    defence or a renewal, never below what the data supports."""
    b = case["buyer"]
    current = b.get("current_unit_price")
    options = [0.9 * their_price]
    if current:
        justified = dossier.justified_move_pct if dossier and dossier.justified_move_pct is not None else 0.0
        options.append(current * (1 + max(0.0, justified) / 100))
        settled = [x for v in (dossier.settled_pct.values() if dossier else []) for x in v]
        if settled:
            options.append(current * (1 + max(0.0, statistics.median(settled)) / 100))
    for sid in case.get("suppliers", []):
        if dossier and (sc := dossier.should_cost.get(sid) or dossier.should_cost.get("*")):
            if sc[0] < their_price:
                options.append(sc[0])
            break
    price = min(options)
    if current and case.get("type") in ("price_increase", "renewal"):
        price = min(price, current)
    return round(max(price, 0.5 * their_price), 2)


def best_combo(ev, space, sid, price):
    """The term sheet with the lowest C for us at `price`."""
    std = ev.std.get(sid)
    return space.complete({"unit_price": price}, std, lambda t: ev.c(sid, t))


def aspiration(c_target, c_res, tau, beta):
    """C we are prepared to reach by time `tau` (0..1): Boulware below beta 1, linear at 1."""
    return c_target + (c_res - c_target) * min(1.0, max(0.0, tau)) ** (1 / beta)


def next_bid(pb, t, a, c_target, c_res, c_their_on_ours, tau):
    """Our C this turn. `t`: SupplierThreadState, `a`: SupplierAssessment, `c_their_on_ours`: their
    price on our best terms - we never offer more than that, nor more than half the gap at once."""
    if not t.my_c:
        return c_target
    last = t.my_c[-1]
    step = pb.k * max(0.0, a.concession)  # reciprocity: their move, in our C
    bid = max(aspiration(c_target, c_res, tau, pb.beta), last + step)
    bid = min(bid, last + 0.5 * max(0.0, c_their_on_ours - last), c_res)
    return max(bid, last)  # never backwards


def generate(ev, space, sid, target_c, their_price, standing=None):
    """Complete term sheets that cost us `target_c` (within a cent), at a price no higher than the
    supplier asks: the C-optimal one plus variants that give the supplier more for the same C."""
    std = ev.std.get(sid)
    base = best_combo(ev, space, sid, their_price)
    combos = space.combos(std)
    if combos is None or len(combos) > MAX_COMBOS:
        combos = [base] + [
            {**base, f: v} for f in space.levers for v in space.options(f, std) if v != base[f]
        ]
    if standing:  # the supplier's own terms with our price: easy for it to say yes to
        combos.append({**base, **{f: v for f, v in standing.items() if f in space.levers}})
    out = []
    for combo in combos:
        terms = {**combo, "unit_price": their_price}
        terms = {f: terms[f] for f in space.negotiable}
        if space.valid(terms, std):
            continue
        price = ev.price_for(sid, terms, target_c)
        if price is None or price > their_price:
            continue
        pkg = CandidatePackage(sid, {**terms, "unit_price": price}, "terms")
        out.append(ev.evaluate(pkg))
    return out


def select(evaluated, base_terms, n=3):
    """Up to `n` diverse sheets: the one worth most to the supplier, the one closest to our ideal
    terms (the highest price - simple suppliers read the price), and one more."""
    if not evaluated:
        return []
    by_cash = sorted(evaluated, key=lambda e: -e.cash_theirs)
    by_price = sorted(evaluated, key=lambda e: -e.terms["unit_price"])
    picks = []
    for e in (by_price[0], by_cash[0], *by_cash[1:]):
        if len(picks) == n:
            break
        if all(_distance(e.terms, p.terms) > 0 for p in picks):
            picks.append(e)
    return picks


def _distance(a, b):
    return sum(a[f] != b[f] for f in a if f != "unit_price")

"""AcceptancePolicy and the turn decision: close (accept the best valid standing sheet, or walk
away), or continue (which thread, at what C). Everything here is code: the model never decides
to accept, to walk, or what a package costs.

Order: a near cap closes; an `agreed` sheet is accepted; a `final_offer` is accepted, mirrored
(its price, our terms - only when the expected gain beats the walk risk) or left for a better
thread; an `open` sheet is accepted once it is as good as our next bid or our rounds are used up
(after a mirror if its open terms cost us); otherwise we bid."""

import math

from ..cost import must_haves_ok
from . import bids
from .assess import assess
from .records import CandidatePackage, DecisionProposal

LIVE = {"open", "final_offer", "agreed"}


def live(cs):
    return [t for t in cs.threads.values() if t.status in LIVE]


def c_of(ev, t, scenario="mid"):
    if not t.offer_id or t.standing.get("unit_price") is None:
        return math.inf
    return ev.c(t.sid, t.standing, scenario)


def feasible(cs, ev, t):
    """A sheet we may take: it exists, keeps the must-haves and beats the alternative (pessimistic C)."""
    return (
        c_of(ev, t) < math.inf
        and must_haves_ok(cs.case, t.standing, t.std)
        and c_of(ev, t, "high") <= cs.c_alt
    )


def closing(cs, ev, reason="close"):
    """The best valid standing sheet across all threads, else walk away (the alternative)."""
    ok = [t for t in live(cs) if feasible(cs, ev, t)]
    if not ok:
        sid = (live(cs) or list(cs.threads.values()))[0].sid
        return DecisionProposal("walk", sid, reason=f"{reason}: no sheet beats the alternative")
    t = min(ok, key=lambda t: c_of(ev, t))
    return DecisionProposal("accept", t.sid, term_sheet_id=t.offer_id, reason=f"{reason}: best valid sheet")


def epsilon(cs):
    """What counts as 'as good as': 1 % of the room between our target and our limit."""
    spans = [res - target for target, res in cs.targets.values() if math.isfinite(res - target)]
    return 0.01 * max(spans or [1.0])


def mirror(cs, ev, space, t, keep_stated):
    """Their price with our terms for every field they left open (`keep_stated`) or for every field;
    None unless it saves us more than epsilon."""
    if t.standing.get("unit_price") is None:
        return None
    keep = {f: v for f, v in t.standing.items() if f in space.levers} if keep_stated else {}
    terms = space.complete({**keep, "unit_price": t.standing["unit_price"]}, t.std, lambda x: ev.c(t.sid, x))
    if space.valid(terms, t.std) or c_of(ev, t) - ev.c(t.sid, terms) <= epsilon(cs):
        return None
    return ev.evaluate(CandidatePackage(t.sid, terms, "mirror"))


def decide(cs, ev, space, order, urgent=False):
    """The next move. `order`: live supplier IDs, most urgent first. `urgent`: the wave's cap is near."""
    pb = cs.playbook
    threads = live(cs)
    if urgent or not threads:
        return closing(cs, ev, "cap near" if urgent else "no live thread")
    eps = epsilon(cs)
    agreed = [t for t in threads if t.status == "agreed" and feasible(cs, ev, t)]
    if agreed:
        best = min((t for t in threads if feasible(cs, ev, t)), key=lambda t: c_of(ev, t))
        return DecisionProposal("accept", best.sid, term_sheet_id=best.offer_id, reason="agreed: take the best sheet")
    for sid in order:
        t = cs.threads[sid]
        if t.status not in LIVE:
            continue
        others = [o for o in threads if o.sid != t.sid]
        c_now = c_of(ev, t)
        dominates = all(c_now <= c_of(ev, o) for o in others)
        if t.status == "final_offer":
            if feasible(cs, ev, t) and dominates:
                m = mirror(cs, ev, space, t, keep_stated=True) if pb.mirror_final and t.moves_left > 0 else None
                if m and (1 - pb.p_walk) * (c_now - m.c) > pb.p_walk * max(0.0, cs.c_alt - c_now):
                    return DecisionProposal("send", t.sid, (m,), reason="final offer: its price on our open terms")
                return DecisionProposal("accept", t.sid, term_sheet_id=t.offer_id, reason="final offer: best sheet")
            if any(o.status != "final_offer" for o in others):
                continue  # a better thread may still move: never push a final offer
            return closing(cs, ev, "all final")
        if t.moves_left <= 0:
            if feasible(cs, ev, t) and dominates:
                return DecisionProposal("accept", t.sid, term_sheet_id=t.offer_id, reason="no rounds left")
            continue
        a = assess(t)
        c_target, c_res = cs.targets[t.sid]
        their_price = t.standing.get("unit_price")
        if their_price is None:
            continue  # no price quoted: nothing to bid against
        ours_at_theirs = ev.c(t.sid, bids.best_combo(ev, space, t.sid, their_price))
        tau = max(cs.tau, t.rounds_used / max(pb.max_rounds, 1))
        next_c = bids.next_bid(pb, t, a, c_target, c_res, ours_at_theirs, tau)
        time_up = t.moves_left <= 1 or t.rounds_used >= pb.max_rounds
        can_accept = t.rounds_used >= pb.min_rounds_accept and feasible(cs, ev, t) and dominates
        if can_accept and not (a.regressed and not time_up) and (c_now <= next_c + eps or time_up):
            m = mirror(cs, ev, space, t, keep_stated=False)
            if m and m.c < next_c + eps:
                return DecisionProposal("send", t.sid, (m,), reason="close: its price on our terms")
            return DecisionProposal("accept", t.sid, term_sheet_id=t.offer_id, reason="as good as our next bid")
        packages = bids.select(bids.generate(ev, space, t.sid, next_c, their_price, t.standing))
        if packages:
            return DecisionProposal("send", t.sid, tuple(packages), reason=f"bid at C {next_c:,.0f}")
    return closing(cs, ev, "nothing left to bid")

"""BuyerAgent: one case, one writer. Each turn it rebuilds the canonical state from the arena's
threads, lets code decide (close, or which thread at what C with which packages and claims), lets
the model phrase it (or the template, when the model is slow, absent or wrong), and passes every
move through the guard. Plugs into `play()` like any agent: `decide(case, threads)`."""

import logging
import math
import time

from ..docs import standard_terms
from ..play import latest, moves_left
from . import bids
from .acceptance import decide, live
from .economics import EconomicEvaluator, estimate_supplier
from .guard import GuardReject, check_message, pick_claims
from .playbook import playbook
from .records import CaseState, SupplierThreadState
from .space import ContractSpace
from .writer import disclosure, template, write

log = logging.getLogger("arena")
ENDED = {"walked_away", "no_bid"}


class BuyerAgent:
    def __init__(self, package=None, model=None, decisions=None, store=None, clock=time.monotonic):
        self.package, self.model, self.decisions, self.store, self.clock = package, model, decisions, store, clock
        self.case_id = None
        self.deadline = None  # set by play(): the wave's cap (time.time()), or a function returning it
        self.seen, self.since = {}, {}  # sid -> supplier messages seen / monotonic time the last arrived
        self.started = None

    # -- preparation (before the clock matters) -------------------------------------------------
    def prepare(self, case):
        from .dossier import build_dossier  # the data layer is optional: no package, no dossier

        self.case_id, self.started = case["case_id"], self.clock()
        self.dossier = build_dossier(self.package, case) if self.package else None
        adjust = {}
        if self.model is not None and self.dossier is not None:
            from .writer import prep

            adjust = prep(self.model, case, self.dossier) or {}
        self.playbook = playbook(case, adjust)
        self.space = ContractSpace(case)
        self.seen, self.since = {}, {}

    # -- canonical state ----------------------------------------------------------------------
    def observe(self, case, threads):
        now = self.clock()
        states = {}
        std = {sid: standard_terms(ev) for sid, ev in threads.items()}
        estimates = {}
        if self.playbook.relationship:
            for sid, ev in threads.items():
                price = (latest(ev).get("term_sheets") or [{}])[0].get("terms", {}).get("unit_price")
                if price:
                    cash = bool(self.dossier and self.dossier.cash_pressure.get(sid))
                    estimates[sid] = estimate_supplier(self.dossier, sid, price, cash)
        econ = EconomicEvaluator(case, std, estimates)
        for sid, ev in threads.items():
            last = latest(ev)
            n = sum(m.get("from") != "buyer" for m in ev)
            if self.seen.get(sid) != n:
                self.seen[sid], self.since[sid] = n, now
            sheets = last.get("term_sheets") or []
            theirs = [m for m in ev if m.get("from") != "buyer" and m.get("term_sheets")]
            mine = [m for m in ev if m.get("from") == "buyer" and m.get("term_sheets")]
            states[sid] = SupplierThreadState(
                sid=sid,
                offer_id=sheets[0]["term_sheet_id"] if sheets else None,
                status=last.get("status") or "open",
                standing=sheets[0]["terms"] if sheets else {},
                std=std[sid],
                missing=last.get("missing_fields") or [],
                rounds_used=sum(m.get("from") == "buyer" for m in ev),
                moves_left=moves_left(case, ev),
                their_c=[econ.c(sid, m["term_sheets"][0]["terms"]) for m in theirs],
                my_c=[max(econ.c(sid, s["terms"]) for s in m["term_sheets"]) for m in mine],
                claim_results=last.get("claim_results") or [],
                last_body=last.get("body") or "",
                rev=len(ev),
            )
        cs = CaseState(case, self.playbook, self.dossier, states, c_alt=econ.c_alt())
        cited, cited_to = set(), {}
        for sid, ev in threads.items():
            for m in ev:
                if m.get("from") == "buyer":
                    for ref in m.get("refs") or []:
                        (cited_to.setdefault(sid, set()) if ref.startswith(("quote:", "offer:")) else cited).add(ref)
        cs.cited, cs.cited_to = cited, cited_to
        for sid, t in states.items():
            opening = (theirs_first := next((m for m in threads[sid] if m.get("term_sheets")), None)) and theirs_first[
                "term_sheets"
            ][0]["terms"].get("unit_price")
            if not opening:
                continue
            anchor = bids.anchor_price(case, self.dossier, opening)
            c_target = econ.c(sid, bids.best_combo(econ, self.space, sid, anchor))
            c_open = econ.c(sid, {**threads[sid][0]["term_sheets"][0]["terms"]}) if t.their_c else math.inf
            c_res = min(cs.c_alt, c_open, max(t.their_c or [math.inf]))
            if not math.isfinite(c_res):
                c_res = econ.c(sid, bids.best_combo(econ, self.space, sid, opening))
            cs.targets[sid] = (c_target, max(c_target, c_res - 0.01 * abs(c_res - c_target)))
        cs.tau = self.time_used()
        return cs, econ

    def time_used(self):
        """0..1: how much of the wave's time has gone (0 without a cap)."""
        cap = self.deadline() if callable(self.deadline) else self.deadline
        if not cap or self.started is None:
            return 0.0
        total = cap - (time.time() - (self.clock() - self.started))
        return min(1.0, max(0.0, (self.clock() - self.started) / max(total, 1.0)))

    # -- one turn -------------------------------------------------------------------------------
    def decide(self, case, threads):
        t0 = self.clock()
        if case["case_id"] != self.case_id:
            self.prepare(case)
        cs, econ = self.observe(case, threads)
        order = sorted((t.sid for t in live(cs)), key=lambda s: self.since.get(s, 0.0))
        proposal = decide(cs, econ, self.space, order)
        log.info("%s %s %s: %s", case["case_id"], proposal.kind, proposal.sid, proposal.reason)
        if proposal.kind == "accept":
            return {
                "supplier_id": proposal.sid,
                "message": {"action": {"type": "accept", "term_sheet_id": proposal.term_sheet_id}},
            }
        if proposal.kind == "walk":
            return {"supplier_id": proposal.sid, "message": {"action": {"type": "walk_away"}}}
        t = cs.threads[proposal.sid]
        claims = pick_claims(cs, proposal.sid)
        packet = disclosure(cs, t, proposal, claims)
        budget = self.budget(t0)
        msg = write(self.model, packet, budget) if self.model is not None and budget > 3 else template(packet)
        try:
            msg = check_message(cs, econ, self.space, proposal, packet, msg)
        except GuardReject as e:  # the model's text failed the guard: the template always passes
            log.warning("%s guard: %s - template instead", case["case_id"], e)
            msg = check_message(cs, econ, self.space, proposal, packet, template(packet))
        return {"supplier_id": proposal.sid, "message": msg.payload()}

    def budget(self, t0):
        """Seconds the writer may take: the playbook's budget within the 60 s per message."""
        spent = self.clock() - t0
        return min(self.playbook.llm_budget_s, 60.0 - self.playbook.send_margin_s - spent)

