"""The Communication step: a DisclosurePacket (approved facts, claims, packages) becomes the
e-mail. The template always works; the model version (`write`) is added in the LLM layer."""

from .records import DisclosurePacket, PublicMessage

QUESTIONS = {
    "breakdown": "Could you send us a cost breakdown for this part?",
    "lead_time": "What is the shortest lead time you can confirm?",
    "variant": "Is there a cheaper variant or specification you would suggest?",
}


def disclosure(cs, t, proposal, claims):
    sheets = tuple(p.terms for p in proposal.packages)
    numbers = {_num(v) for s in sheets for v in s.values() if isinstance(v, int | float)}
    return DisclosurePacket(
        sid=t.sid,
        mode=cs.playbook.mode,
        goal=cs.playbook.goal,
        rev=t.rev,
        packages=sheets,
        claims=tuple(claims),
        question=proposal.question,
        their_last=t.last_body[:1500],
        allowed_numbers=frozenset(numbers),
        subject=f"Re: {cs.case['title']}",
    )


def _num(v):
    return f"{v:.2f}" if isinstance(v, float) else str(v)


def template(pkt: DisclosurePacket) -> PublicMessage:
    """The deterministic e-mail: polite, the claims verbatim, the packages described by the sheets."""
    lines = ["Dear Sir or Madam,", "", "thank you for your message."]
    lines += [c.sentence for c in pkt.claims]
    if len(pkt.packages) > 1:
        lines.append("We attach alternative packages; any of them works for us.")
    elif pkt.packages:
        lines.append("Please find our proposal in the attached term sheet.")
    if pkt.question:
        lines.append(QUESTIONS.get(pkt.question, pkt.question))
    lines += ["", "Best regards", "Hollerau Pumpenwerke, Purchasing"]
    refs = tuple(dict.fromkeys(i for c in pkt.claims for i in c.ids))
    return PublicMessage(pkt.subject, "\n".join(lines), pkt.packages, refs)


def write(model, pkt, budget_s):
    """The model's e-mail within `budget_s`; the template when it cannot."""
    return template(pkt)


def prep(model, case, dossier):
    """Playbook adjustments from the preparation call (bounded by `playbook.bounded`)."""
    return {}

"""The guard: every move - the model's, a repaired one, the template - passes here before it is
sent. Package validity, the claim rules (at most 3 checked IDs, each once per case, a rival's quote
once per supplier), message limits and privacy."""

import re

from .records import PublicMessage

ID_RE = re.compile(r"\b(?:idx|quote|offer|sc|qn|po|cost|fc|news|doc|ctr|sup|part|gr|inv|rfq):[\w.:@#/-]*\w")
MAX_CLAIMS, MAX_SUBJECT, MAX_BODY, MAX_REFS = 3, 300, 8000, 20


class GuardReject(Exception):
    pass


def pick_claims(cs, sid, limit=MAX_CLAIMS):
    """The strongest unused claims for this supplier, at most `limit` IDs-sets."""
    if cs.dossier is None:
        return ()
    used, to = cs.cited, cs.cited_to.get(sid, set())
    out = []
    for c in sorted(cs.dossier.claims, key=lambda c: -c.strength):
        if c.suppliers and sid not in c.suppliers:
            continue
        if any((i in to) if c.per_supplier else (i in used) for i in c.ids):
            continue
        out.append(c)
        if len(out) == limit:
            break
    return tuple(out)


def check_message(cs, econ, space, proposal, packet, msg):
    """The message as it may go out, or GuardReject."""
    t = cs.threads[proposal.sid]
    sheets = list(msg.term_sheets)
    if len(sheets) > 3:
        raise GuardReject("more than 3 term sheets")
    for s in sheets:
        if errors := space.valid(s, t.std):
            raise GuardReject(f"invalid term sheet: {errors}")
    approved = {i for c in packet.claims for i in c.ids}
    if not set(msg.refs) <= approved:
        raise GuardReject(f"refs not approved: {set(msg.refs) - approved}")
    body = ID_RE.sub(lambda m: m.group(0) if m.group(0) in approved else "", msg.body)
    if len(approved) > MAX_CLAIMS * 2 or len(msg.refs) > MAX_REFS:
        raise GuardReject("too many refs")
    return PublicMessage(msg.subject[:MAX_SUBJECT], body.strip()[:MAX_BODY], tuple(sheets), tuple(msg.refs))

"""EvidenceDossier: what the data says about this case, before the session opens."""

from ..agents.evidence import dossier as render
from .records import EvidenceDossier


def build_dossier(package, case):
    return EvidenceDossier(case_id=case["case_id"], text=render(package, case))
